CREATE TABLE practice.items (
    item_id VARCHAR(10) NOT NULL,
    description VARCHAR(100) NOT NULL,
    hts10 VARCHAR(10) NULL,
    country_of_origin CHAR(2) NOT NULL,
    supplier_id VARCHAR(10) NOT NULL,
    std_cost DECIMAL(18,4) NOT NULL,
    list_price DECIMAL(18,2) NOT NULL,
    usmca_eligible_flag CHAR(1) NOT NULL,
    CONSTRAINT pk_items PRIMARY KEY (item_id)
);
GO
CREATE TABLE practice.suppliers (
    supplier_id VARCHAR(10) NOT NULL,
    supplier_name VARCHAR(60) NOT NULL,
    supplier_country CHAR(2) NOT NULL,
    supplier_type VARCHAR(20) NOT NULL,
    CONSTRAINT pk_suppliers PRIMARY KEY (supplier_id)
);
GO
CREATE TABLE practice.brokers (
    broker_id VARCHAR(10) NOT NULL,
    broker_name VARCHAR(60) NOT NULL,
    import_country CHAR(2) NOT NULL,
    CONSTRAINT pk_brokers PRIMARY KEY (broker_id)
);
GO
CREATE TABLE practice.entries (
    entry_no VARCHAR(12) NOT NULL,
    import_country CHAR(2) NOT NULL,
    entry_date DATE NOT NULL,
    port VARCHAR(40) NOT NULL,
    broker_id VARCHAR(10) NOT NULL,
    CONSTRAINT pk_entries PRIMARY KEY (entry_no)
);
GO
CREATE TABLE practice.entry_lines (
    entry_no VARCHAR(12) NOT NULL,
    line_no INT NOT NULL,
    item_id VARCHAR(10) NOT NULL,
    qty INT NOT NULL,
    entered_value DECIMAL(18,2) NOT NULL,
    duty_rate_applied DECIMAL(9,4) NOT NULL,
    duty_amount DECIMAL(18,2) NOT NULL,
    program_claimed VARCHAR(10) NULL
);
GO
CREATE TABLE practice.duty_rates_reference (
    import_country CHAR(2) NOT NULL,
    hts10 VARCHAR(10) NOT NULL,
    country_of_origin CHAR(2) NOT NULL,
    effective_from DATE NOT NULL,
    effective_to DATE NOT NULL,
    base_rate DECIMAL(9,4) NOT NULL,
    additional_rate DECIMAL(9,4) NOT NULL,
    expected_rate DECIMAL(9,4) NOT NULL,
    CONSTRAINT pk_duty_rates_reference PRIMARY KEY (import_country, hts10, country_of_origin, effective_from)
);
GO
CREATE TABLE practice.receipts (
    receipt_id VARCHAR(12) NOT NULL,
    po_no VARCHAR(12) NOT NULL,
    item_id VARCHAR(10) NOT NULL,
    receipt_date DATE NOT NULL,
    qty INT NOT NULL,
    actual_landed_unit_cost DECIMAL(18,4) NOT NULL,
    CONSTRAINT pk_receipts PRIMARY KEY (receipt_id)
);
GO
CREATE TABLE practice.tariff_scenario (
    scenario_id VARCHAR(10) NOT NULL,
    scenario_name VARCHAR(100) NOT NULL,
    import_country CHAR(2) NOT NULL,
    hts_prefix VARCHAR(10) NOT NULL,
    country_of_origin CHAR(2) NOT NULL,
    additional_rate DECIMAL(9,4) NOT NULL,
    effective_date DATE NOT NULL,
    usmca_exempt CHAR(1) NOT NULL,
    CONSTRAINT pk_tariff_scenario PRIMARY KEY (scenario_id, hts_prefix, country_of_origin)
);
GO
CREATE TABLE practice.work_items (
    work_item_id VARCHAR(10) NOT NULL,
    process VARCHAR(20) NOT NULL,
    item_type VARCHAR(30) NOT NULL,
    title VARCHAR(100) NOT NULL,
    action_ref VARCHAR(10) NULL,
    received_date DATE NOT NULL,
    due_date DATE NOT NULL,
    released_date DATE NULL,
    checker_signoff_date DATE NULL,
    errors_after_release INT NULL,
    CONSTRAINT pk_work_items PRIMARY KEY (work_item_id)
);
GO
